<table>
<thead>
<tr>
<th>参数名</th>
<th>描述</th>
<th>类型</th>
<th style="text-align:center">默认值</th>
</tr>
</thead>
<tbody>
<tr>
<td>model-value <strong>(v-model)</strong></td>
<td>绑定值</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>default-value</td>
<td>默认值（非受控状态）</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>''</code></td>
</tr>
<tr>
<td>size</td>
<td>输入框大小</td>
<td><code v-pre>'xs' | 'sm' | 'md' | 'lg' | 'xl'</code></td>
<td style="text-align:center"><code v-pre>'md'</code></td>
</tr>
<tr>
<td>clearable</td>
<td>是否允许清空输入框</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>disabled</td>
<td>是否禁用</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>readonly</td>
<td>是否为只读状态</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>error</td>
<td>是否为错误状态</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>placeholder</td>
<td>提示文字</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>max-length</td>
<td>输入值的最大长度</td>
<td><code v-pre>number | { length: number; errorOnly?: boolean }</code></td>
<td style="text-align:center"><code v-pre>0</code></td>
</tr>
<tr>
<td>show-word-limit</td>
<td>是否显示字数统计</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>word-length</td>
<td>字符长度的计算方法</td>
<td><code v-pre>(value: string) =&gt; number</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
